{"command":"cat <<'EOF' > src/main.rs
use clap::{Arg, ArgAction, Command};

fn build_cli() -> Command {
    Command::new("executable")
        .disable_version_flag(true)
        .disable_help_flag(true)
        .arg(
            Arg::new("schema")
                .help("The JSON Schema to validate with (i.e. schema.json)")
                .value_name("SCHEMA")
                .index(1),
        )
        .arg(
            Arg::new("instance")
                .short('i')
                .long("instance")
                .help("A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)")
                .value_name("INSTANCES")
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("draft")
                .short('d')
                .long("draft")
                .help("Enforce a specific JSON Schema draft")
                .value_name("DRAFT")
                .value_parser(["4", "6", "7", "2019", "2020"]),
        )
        .arg(
            Arg::new("assert-format")
                .long("assert-format")
                .help("Turn ON format validation")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("no-assert-format")
                .long("no-assert-format")
                .help("Turn OFF format validation")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("output")
                .long("output")
                .help("Select output style: text (default), flag, list, hierarchical")
                .value_name("OUTPUT")
                .default_value("text")
                .value_parser(["text", "flag", "list", "hierarchical"]),
        )
        .arg(
            Arg::new("version")
                .short('v')
                .long("version")
                .help("Show program's version number and exit")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("errors-only")
                .long("errors-only")
                .help("Only show validation errors")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("connect-timeout")
                .long("connect-timeout")
                .help("Timeout for establishing connections (in seconds)")
                .value_name("SECONDS"),
        )
        .arg(
            Arg::new("timeout")
                .long("timeout")
                .help("Timeout for HTTP requests (in seconds)")
                .value_name("SECONDS"),
        )
        .arg(
            Arg::new("insecure")
                .short('k')
                .long("insecure")
                .help("Skip TLS certificate verification (dangerous!)")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("cacert")
                .long("cacert")
                .help("Path to a custom CA certificate file (PEM format)")
                .value_name("FILE"),
        )
        .arg(
            Arg::new("help")
                .short('h')
                .long("help")
                .help("Print help")
                .action(ArgAction::SetTrue),
        )
}

fn main() {
    let mut cmd = build_cli();
    let matches = match cmd.try_get_matches_from_mut(std::env::args()) {
        Ok(m) => m,
        Err(e) => {
            e.exit();
        }
    };
    if matches.get_flag("version") {
        println!("Version: 0.41.0");
        return;
    }
    if matches.get_flag("help") {
        let _ = cmd.print_help();
        println!();
        return;
    }
    let schema_arg = matches.get_one::<String>("schema");
    if schema_arg.is_none() {
        eprintln!("error: the following required arguments were not provided:\n  <SCHEMA>\n\nUsage: executable <SCHEMA>\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    println!("Schema arg: {:?}", schema_arg);
}
EOF

cargo build --release --offline 2>&1
cp target/release/jsonschema_cli /tmp/my_exe
/tmp/my_exe --help"}

