                .help("The JSON Schema to validate with (i.e. schema.json)")
                .value_name("SCHEMA")
                .index(1),
        )
        .arg(
            Arg::new("instance")
                .short('i')
                .long("instance")
                .help("A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)")
                .value_name("INSTANCES")
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("draft")
                .short('d')
                .long("draft")
                .help("Enforce a specific JSON Schema draft")
                .value_name("DRAFT")
                .value_parser(["4", "6", "7", "2019", "2020"]),
        )
        .arg(
            Arg::new("assert-format")
                .long("assert-format")
                .help("Turn ON format validation")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("no-assert-format")
                .long("no-assert-format")
                .help("Turn OFF format validation")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("output")
                .long("output")
                .help("Select output style: text (default), flag, list, hierarchical")
                .value_name("OUTPUT")
                .default_value("text")
                .value_parser(["text", "flag", "list", "hierarchical"]),
        )
        .arg(
            Arg::new("errors-only")
                .long("errors-only")
                .help("Only show validation errors")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("connect-timeout")
                .long("connect-timeout")
                .help("Timeout for establishing connections (in seconds)")
                .value_name("SECONDS"),
        )
        .arg(
            Arg::new("timeout")
                .long("timeout")
                .help("Total timeout for HTTP requests (in seconds)")
                .value_name("SECONDS"),
        )
        .arg(
            Arg::new("insecure")
                .short('k')
                .long("insecure")
                .help("Skip TLS certificate verification (dangerous!)")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("cacert")
                .long("cacert")
                .help("Path to a custom CA certificate file (PEM format)")
                .value_name("FILE"),
        )
        .try_get_matches_from(args)
    {
        Ok(m) => m,
        Err(e) => {
            eprint!("{}", e);
            std::process::exit(2);
        }
    };

    let schema_path_str = match matches.get_one::<String>("schema") {
        Some(s) => s,
        None => {
            eprintln!("error: the following required arguments were not provided:\n  <SCHEMA>\n\nUsage: executable <SCHEMA>\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    };

    let instance_paths: Vec<String> = matches
        .get_many::<String>("instance")
        .map(|vals| vals.cloned().collect())
        .unwrap_or_default();

    let output_style = matches.get_one::<String>("output").map(|s| s.as_str()).unwrap_or("text");
    let errors_only = matches.get_flag("errors-only");

    // Format assertion setting: check last occurrence in args
    let mut assert_format = false;
    for arg in std::env::args() {
        if arg == "--assert-format" {
            assert_format = true;
        } else if arg == "--no-assert-format" {
            assert_format = false;
        }
    }

    let opts = ValidationOptions {
        assert_format,
        draft: matches.get_one::<String>("draft").cloned(),
    };

    // Load schema file
    let schema_content = match fs::read_to_string(schema_path_str) {
        Ok(c) => c,
        Err(e) => {
            println!("Error: {}", e);
            std::process::exit(1);
        }
