use anyhow::{anyhow, Result};
use clap::{Arg, ArgAction, Command};
use indexmap::IndexMap;
use serde::Serialize;
use serde_json::{json, Value};
use std::collections::HashSet;
use std::fs;
use std::path::{Path, PathBuf};
use url::Url;

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct EvaluationNode {
    pub evaluation_path: String,
    pub instance_location: String,
    pub schema_location: String,
    pub valid: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub errors: Option<IndexMap<String, String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub annotations: Option<Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub dropped_annotations: Option<Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub details: Option<Vec<EvaluationNode>>,
}

#[derive(Serialize, Clone, Debug)]
struct OutputEnvelope {
    #[serde(skip_serializing_if = "Option::is_none")]
    instance: Option<String>,
    output: String,
    payload: Value,
    schema: String,
}

struct ValidationOptions {
    assert_format: bool,
}

fn compact_json(v: &Value) -> String {
    serde_json::to_string(v).unwrap_or_else(|_| v.to_string())
}

fn is_type(v: &Value, ty: &str) -> bool {
    match ty {
        "null" => v.is_null(),
        "boolean" => v.is_boolean(),
        "number" => v.is_number(),
        "integer" => {
            if let Some(n) = v.as_number() {
                n.is_i64() || n.is_u64() || (n.is_f64() && n.as_f64().unwrap().fract() == 0.0)
            } else {
                false
            }
        }
        "string" => v.is_string(),
        "array" => v.is_array(),
        "object" => v.is_object(),
        _ => false,
    }
}

fn path_to_file_uri(path_str: &str) -> String {
    let p = Path::new(path_str);
    let abs = if p.is_absolute() {
        p.to_path_buf()
    } else {
        std::env::current_dir().unwrap_or_default().join(p)
    };
    format!("file://{}#", abs.to_string_lossy())
}

struct SchemaContext {
    base_uri: String,
    root_schema: Value,
    schema_dir: PathBuf,
}

impl SchemaContext {
    fn resolve_pointer<'a>(&'a self, root: &'a Value, pointer: &str) -> Option<&'a Value> {
        if pointer.is_empty() || pointer == "#" {
            return Some(root);
        }
        let p = if pointer.starts_with("#/") {
            &pointer[1..]
        } else if pointer.starts_with('/') {
            pointer
        } else {
            return None;
        };
        root.pointer(p)
    }

    fn resolve_ref(&self, ref_str: &str) -> Result<(Value, String)> {
        if ref_str.starts_with('#') {
            if let Some(sub) = self.resolve_pointer(&self.root_schema, ref_str) {
                let loc = format!("{}{}", self.base_uri.trim_end_matches('#'), ref_str);
                Ok((sub.clone(), loc))
            } else {
                Err(anyhow!("Cannot resolve ref {}", ref_str))
            }
        } else if ref_str.starts_with("http://") || ref_str.starts_with("https://") {
            Err(anyhow!(
                "Resource '{}' is not present in a registry and retrieving it failed: error sending request for url ({})",
                ref_str, ref_str
            ))
        } else {
            let (file_part, frag) = if let Some(idx) = ref_str.find('#') {
                (&ref_str[..idx], &ref_str[idx..])
            } else {
                (ref_str, "")
            };
            let target_path = self.schema_dir.join(file_part);
            let content = fs::read_to_string(&target_path)
                .map_err(|_| anyhow!("Resource '{}' is not present in a registry", ref_str))?;
            let sub_json: Value = serde_json::from_str(&content)?;
            let file_uri = path_to_file_uri(&target_path.to_string_lossy());
            let loc = if frag.is_empty() {
                file_uri
            } else {
                format!("{}{}", file_uri.trim_end_matches('#'), frag)
            };
            if frag.is_empty() || frag == "#" {
                Ok((sub_json, loc))
            } else if let Some(sub) = self.resolve_pointer(&sub_json, frag) {
                Ok((sub.clone(), loc))
            } else {
                Err(anyhow!("Cannot resolve ref {}", ref_str))
            }
        }
    }
}

fn validate_schema_meta(schema: &Value) -> Result<()> {
    if schema.is_boolean() {
        return Ok(());
    }
    let obj = match schema.as_object() {
        Some(o) => o,
        None => return Err(anyhow!("Schema must be an object or boolean")),
    };

    if let Some(ty) = obj.get("type") {
        let valid_types = [
            "null", "boolean", "number", "integer", "string", "array", "object",
        ];
        if let Some(s) = ty.as_str() {
            if !valid_types.contains(&s) {
                return Err(anyhow!(
                    "\"{}\" is not valid under any of the schemas listed in the 'anyOf' keyword",
                    s
                ));
            }
        } else if let Some(arr) = ty.as_array() {
            for item in arr {
                if let Some(s) = item.as_str() {
                    if !valid_types.contains(&s) {
                        return Err(anyhow!("\"{}\" is not a valid type", s));
                    }
                } else {
                    return Err(anyhow!("Type array elements must be strings"));
                }
            }
        } else {
            return Err(anyhow!(
                "{} is not valid under any of the schemas listed in the 'anyOf' keyword",
                compact_json(ty)
            ));
        }
    }

    if let Some(min) = obj.get("minimum") {
        if !min.is_number() {
            return Err(anyhow!(
                "{} is not of type \"number\"",
                compact_json(min)
            ));
        }
    }

    if let Some(pat) = obj.get("pattern") {
        if let Some(p) = pat.as_str() {
            if regex::Regex::new(p).is_err() {
                return Err(anyhow!("\"{}\" is not a \"regex\"", p));
            }
        }
    }

    if let Some(props) = obj.get("properties").and_then(|v| v.as_object()) {
        for v in props.values() {
            validate_schema_meta(v)?;
        }
    }
    if let Some(arr) = obj.get("allOf").and_then(|v| v.as_array()) {
        for v in arr {
            validate_schema_meta(v)?;
        }
    }
    if let Some(arr) = obj.get("anyOf").and_then(|v| v.as_array()) {
        for v in arr {
            validate_schema_meta(v)?;
        }
    }
    if let Some(arr) = obj.get("oneOf").and_then(|v| v.as_array()) {
        for v in arr {
            validate_schema_meta(v)?;
        }
    }

    Ok(())
}

fn make_kw_node(
    kw: &str,
    eval_path: &str,
    inst_loc: &str,
    schema_loc: &str,
    valid: bool,
    err_msg: Option<String>,
) -> EvaluationNode {
    let mut err_map = None;
    if let Some(msg) = err_msg {
        let mut map = IndexMap::new();
        map.insert(kw.to_string(), msg);
        err_map = Some(map);
    }
    EvaluationNode {
        evaluation_path: format!("{}/{}", eval_path, kw),
        instance_location: inst_loc.to_string(),
        schema_location: format!("{}/{}", schema_loc, kw),
        valid,
        errors: err_map,
        annotations: None,
        dropped_annotations: None,
        details: None,
    }
}

fn evaluate_instance(
    schema: &Value,
    instance: &Value,
    eval_path: &str,
    inst_loc: &str,
    schema_loc: &str,
    ctx: &SchemaContext,
    opts: &ValidationOptions,
) -> EvaluationNode {
    let mut node = EvaluationNode {
        evaluation_path: eval_path.to_string(),
        instance_location: inst_loc.to_string(),
        schema_location: schema_loc.to_string(),
        valid: true,
        errors: None,
        annotations: None,
        dropped_annotations: None,
        details: None,
    };

    if let Some(b) = schema.as_bool() {
        if !b {
            node.valid = false;
            let mut errs = IndexMap::new();
            errs.insert(
                "false".to_string(),
                format!("False schema does not allow {}", compact_json(instance)),
            );
            node.errors = Some(errs);
        }
        return node;
    }

    let obj = match schema.as_object() {
        Some(o) => o,
        None => return node,
    };

    if let Some(r) = obj.get("$ref").and_then(|v| v.as_str()) {
        match ctx.resolve_ref(r) {
            Ok((ref_schema, ref_loc)) => {
                let next_eval = if eval_path.is_empty() {
                    "/$ref".to_string()
                } else {
                    format!("{}/$ref", eval_path)
                };
                let child = evaluate_instance(
                    &ref_schema,
                    instance,
                    &next_eval,
                    inst_loc,
                    &ref_loc,
                    ctx,
                    opts,
                );
                node.valid = child.valid;
                node.details = Some(vec![child]);
                return node;
            }
            Err(e) => {
                node.valid = false;
                let mut errs = IndexMap::new();
                errs.insert("$ref".to_string(), e.to_string());
                node.errors = Some(errs);
                return node;
            }
        }
    }

    let mut children = Vec::new();

    // 1. type
    if let Some(ty_val) = obj.get("type") {
        if let Some(s) = ty_val.as_str() {
            let valid = is_type(instance, s);
            let msg = if !valid {
                Some(format!("{} is not of type \"{}\"", compact_json(instance), s))
            } else {
                None
            };
            children.push(make_kw_node("type", eval_path, inst_loc, schema_loc, valid, msg));
        } else if let Some(arr) = ty_val.as_array() {
            let types: Vec<&str> = arr.iter().filter_map(|x| x.as_str()).collect();
            let matched = types.iter().any(|t| is_type(instance, t));
            let msg = if !matched {
                let mut sorted_types = types.clone();
                sorted_types.sort();
                let types_str = sorted_types
                    .iter()
                    .map(|t| format!("\"{}\"", t))
                    .collect::<Vec<_>>()
                    .join(", ");
                Some(format!("{} is not of types {}", compact_json(instance), types_str))
            } else {
                None
            };
            children.push(make_kw_node("type", eval_path, inst_loc, schema_loc, matched, msg));
        }
    }

    // 2. enum
    if let Some(enum_val) = obj.get("enum").and_then(|v| v.as_array()) {
        let matched = enum_val.contains(instance);
        let msg = if !matched {
            let options: Vec<String> = enum_val.iter().map(compact_json).collect();
            let options_str = if options.len() > 1 {
                let last = &options[options.len() - 1];
                let rest = &options[..options.len() - 1];
                format!("{} or {}", rest.join(", "), last)
            } else {
                options.join("")
            };
            Some(format!("{} is not one of {}", compact_json(instance), options_str))
        } else {
            None
        };
        children.push(make_kw_node("enum", eval_path, inst_loc, schema_loc, matched, msg));
    }

    // 3. const
    if let Some(const_val) = obj.get("const") {
        let matched = instance == const_val;
        let msg = if !matched {
            Some(format!("{} was expected", compact_json(const_val)))
        } else {
            None
        };
        children.push(make_kw_node("const", eval_path, inst_loc, schema_loc, matched, msg));
    }

    // 4. Number
    if let Some(num) = instance.as_f64() {
        if let Some(min) = obj.get("minimum").and_then(|v| v.as_f64()) {
            let valid = num >= min;
            let msg = if !valid {
                Some(format!("{} is less than the minimum of {}", num, min))
            } else {
                None
            };
            children.push(make_kw_node("minimum", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(max) = obj.get("maximum").and_then(|v| v.as_f64()) {
            let valid = num <= max;
            let msg = if !valid {
                Some(format!("{} is greater than the maximum of {}", num, max))
            } else {
                None
            };
            children.push(make_kw_node("maximum", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(ex_min) = obj.get("exclusiveMinimum").and_then(|v| v.as_f64()) {
            let valid = num > ex_min;
            let msg = if !valid {
                Some(format!("{} is less than or equal to the minimum of {}", num, ex_min))
            } else {
                None
            };
            children.push(make_kw_node("exclusiveMinimum", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(ex_max) = obj.get("exclusiveMaximum").and_then(|v| v.as_f64()) {
            let valid = num < ex_max;
            let msg = if !valid {
                Some(format!("{} is greater than or equal to the maximum of {}", num, ex_max))
            } else {
                None
            };
            children.push(make_kw_node("exclusiveMaximum", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(mult) = obj.get("multipleOf").and_then(|v| v.as_f64()) {
            let valid = (num / mult).fract().abs() < 1e-9;
            let msg = if !valid {
                Some(format!("{} is not a multiple of {}", num, mult))
            } else {
                None
            };
            children.push(make_kw_node("multipleOf", eval_path, inst_loc, schema_loc, valid, msg));
        }
    }

    // 5. String
    if let Some(s) = instance.as_str() {
        let char_count = s.chars().count();
        if let Some(min_len) = obj.get("minLength").and_then(|v| v.as_u64()) {
            let valid = (char_count as u64) >= min_len;
            let msg = if !valid {
                let suffix = if min_len == 1 { "character" } else { "characters" };
                Some(format!("{} is shorter than {} {}", compact_json(instance), min_len, suffix))
            } else {
                None
            };
            children.push(make_kw_node("minLength", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(max_len) = obj.get("maxLength").and_then(|v| v.as_u64()) {
            let valid = (char_count as u64) <= max_len;
            let msg = if !valid {
                let suffix = if max_len == 1 { "character" } else { "characters" };
                Some(format!("{} is longer than {} {}", compact_json(instance), max_len, suffix))
            } else {
                None
            };
            children.push(make_kw_node("maxLength", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(pat_str) = obj.get("pattern").and_then(|v| v.as_str()) {
            if let Ok(re) = regex::Regex::new(pat_str) {
                let valid = re.is_match(s);
                let msg = if !valid {
                    Some(format!("{} does not match \"{}\"", compact_json(instance), pat_str))
                } else {
                    None
                };
                children.push(make_kw_node("pattern", eval_path, inst_loc, schema_loc, valid, msg));
            }
        }
        if opts.assert_format {
            if let Some(fmt) = obj.get("format").and_then(|v| v.as_str()) {
                let valid = match fmt {
                    "email" => s.contains('@') && !s.starts_with('@') && !s.ends_with('@'),
                    "ipv4" => s.parse::<std::net::Ipv4Addr>().is_ok(),
                    "ipv6" => s.parse::<std::net::Ipv6Addr>().is_ok(),
                    "uuid" => s.len() == 36 && s.chars().all(|c| c.is_ascii_hexdigit() || c == '-'),
                    "date-time" => s.contains('T') || s.contains('t'),
                    "uri" => Url::parse(s).is_ok(),
                    _ => true,
                };
                let msg = if !valid {
                    Some(format!("{} is not a \"{}\"", compact_json(instance), fmt))
                } else {
                    None
                };
                children.push(make_kw_node("format", eval_path, inst_loc, schema_loc, valid, msg));
            }
        }
    }

    // 6. Array
    if let Some(arr) = instance.as_array() {
        if let Some(min_items) = obj.get("minItems").and_then(|v| v.as_u64()) {
            let valid = (arr.len() as u64) >= min_items;
            let msg = if !valid {
                let suffix = if min_items == 1 { "item" } else { "items" };
                Some(format!("{} has less than {} {}", compact_json(instance), min_items, suffix))
            } else {
                None
            };
            children.push(make_kw_node("minItems", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(max_items) = obj.get("maxItems").and_then(|v| v.as_u64()) {
            let valid = (arr.len() as u64) <= max_items;
            let msg = if !valid {
                let suffix = if max_items == 1 { "item" } else { "items" };
                Some(format!("{} has more than {} {}", compact_json(instance), max_items, suffix))
            } else {
                None
            };
            children.push(make_kw_node("maxItems", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(uniq) = obj.get("uniqueItems").and_then(|v| v.as_bool()) {
            if uniq {
                let mut set = HashSet::new();
                let mut is_uniq = true;
                for item in arr {
                    let s = compact_json(item);
                    if !set.insert(s) {
                        is_uniq = false;
                        break;
                    }
                }
                let msg = if !is_uniq {
                    Some(format!("{} has non-unique elements", compact_json(instance)))
                } else {
                    None
                };
                children.push(make_kw_node("uniqueItems", eval_path, inst_loc, schema_loc, is_uniq, msg));
            }
        }
        if let Some(contains_schema) = obj.get("contains") {
            let mut any_match = false;
            for item in arr {
                let child = evaluate_instance(
                    contains_schema,
                    item,
                    &format!("{}/contains", eval_path),
                    inst_loc,
                    &format!("{}/contains", schema_loc),
                    ctx,
                    opts,
                );
                if child.valid {
                    any_match = true;
                    break;
                }
            }
            let msg = if !any_match {
                Some(format!("None of {} are valid under the given schema", compact_json(instance)))
            } else {
                None
            };
            children.push(make_kw_node("contains", eval_path, inst_loc, schema_loc, any_match, msg));
        }
    }

    // 7. Object
    if let Some(inst_obj) = instance.as_object() {
        if let Some(min_p) = obj.get("minProperties").and_then(|v| v.as_u64()) {
            let valid = (inst_obj.len() as u64) >= min_p;
            let msg = if !valid {
                let suffix = if min_p == 1 { "property" } else { "properties" };
                Some(format!("{} has less than {} {}", compact_json(instance), min_p, suffix))
            } else {
                None
            };
            children.push(make_kw_node("minProperties", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(max_p) = obj.get("maxProperties").and_then(|v| v.as_u64()) {
            let valid = (inst_obj.len() as u64) <= max_p;
            let msg = if !valid {
                let suffix = if max_p == 1 { "property" } else { "properties" };
                Some(format!("{} has more than {} {}", compact_json(instance), max_p, suffix))
            } else {
                None
            };
            children.push(make_kw_node("maxProperties", eval_path, inst_loc, schema_loc, valid, msg));
        }

        // required
        if let Some(req_arr) = obj.get("required").and_then(|v| v.as_array()) {
            let mut req_node = make_kw_node("required", eval_path, inst_loc, schema_loc, true, None);
            let mut req_errs = IndexMap::new();
            for req_item in req_arr {
                if let Some(req_str) = req_item.as_str() {
                    if !inst_obj.contains_key(req_str) {
                        req_node.valid = false;
                        req_errs.insert(
                            "required".to_string(),
                            format!("\"{}\" is a required property", req_str),
                        );
                    }
                }
            }
            if !req_node.valid {
                req_node.errors = Some(req_errs);
            }
            children.push(req_node);
        }

        // dependentRequired / dependencies
        let dep_req = obj.get("dependentRequired").or_else(|| obj.get("dependencies"));
        if let Some(dep_map) = dep_req.and_then(|v| v.as_object()) {
            for (prop_key, dep_val) in dep_map {
                if inst_obj.contains_key(prop_key) {
                    if let Some(dep_arr) = dep_val.as_array() {
                        for dep_item in dep_arr {
                            if let Some(dep_str) = dep_item.as_str() {
                                if !inst_obj.contains_key(dep_str) {
                                    let msg = Some(format!("\"{}\" is a required property", dep_str));
                                    children.push(make_kw_node("required", eval_path, inst_loc, schema_loc, false, msg));
                                }
                            }
                        }
                    }
                }
            }
        }

        // properties
        let empty_map = serde_json::Map::new();
        let props = obj.get("properties").and_then(|v| v.as_object()).unwrap_or(&empty_map);
        let has_props_kw = obj.contains_key("properties");

        if has_props_kw {
            let child_eval = format!("{}/properties", eval_path);
            let child_loc = format!("{}/properties", schema_loc);
            let mut prop_children = Vec::new();
            let mut evaluated_keys = Vec::new();

            for (p_name, p_schema) in props {
                if let Some(p_val) = inst_obj.get(p_name) {
                    evaluated_keys.push(p_name.clone());
                    let p_eval = format!("{}/{}", child_eval, p_name);
                    let p_inst_loc = format!("{}/{}", inst_loc, p_name);
                    let p_schema_loc = format!("{}/{}", child_loc, p_name);
                    let p_child = evaluate_instance(
                        p_schema,
                        p_val,
                        &p_eval,
                        &p_inst_loc,
                        &p_schema_loc,
                        ctx,
                        opts,
                    );
                    prop_children.push(p_child);
                }
            }

            let props_valid = prop_children.iter().all(|c| c.valid);
            let child_node = EvaluationNode {
                evaluation_path: child_eval,
                instance_location: inst_loc.to_string(),
                schema_location: child_loc,
                valid: props_valid,
                errors: None,
                annotations: if props_valid {
                    let mut keys: Vec<Value> = evaluated_keys.iter().map(|k| json!(k)).collect();
                    keys.sort_by(|a, b| a.as_str().cmp(&b.as_str()));
                    Some(json!(keys))
                } else {
                    None
                },
                dropped_annotations: if !props_valid {
                    let mut keys: Vec<Value> = evaluated_keys.iter().map(|k| json!(k)).collect();
                    keys.sort_by(|a, b| a.as_str().cmp(&b.as_str()));
                    Some(json!(keys))
                } else {
                    None
                },
                details: if prop_children.is_empty() { None } else { Some(prop_children) },
            };
            children.push(child_node);
        }

        // additionalProperties
        if let Some(add_props) = obj.get("additionalProperties") {
            let known_keys: HashSet<&String> = props.keys().collect();
            let unexpected_keys: Vec<&String> = inst_obj
                .keys()
                .filter(|k| !known_keys.contains(k))
                .collect();

            if let Some(b) = add_props.as_bool() {
                if !b && !unexpected_keys.is_empty() {
                    if has_props_kw {
                        let msg = Some(format!(
                            "Additional properties are not allowed ('{}' was unexpected)",
                            unexpected_keys[0]
                        ));
                        children.push(make_kw_node("additionalProperties", eval_path, inst_loc, schema_loc, false, msg));
                    } else {
                        for k in unexpected_keys {
                            let msg = Some(format!("False schema does not allow {}", compact_json(&inst_obj[k])));
                            children.push(make_kw_node("false", eval_path, inst_loc, schema_loc, false, msg));
                        }
                    }
                }
            } else if add_props.is_object() {
                for k in unexpected_keys {
                    let p_eval = format!("{}/additionalProperties", eval_path);
                    let p_inst_loc = format!("{}/{}", inst_loc, k);
                    let p_schema_loc = format!("{}/additionalProperties", schema_loc);
                    let p_child = evaluate_instance(
                        add_props,
                        &inst_obj[k],
                        &p_eval,
                        &p_inst_loc,
                        &p_schema_loc,
                        ctx,
                        opts,
                    );
                    children.push(p_child);
                }
            }
        }
    }

    // 8. Combinators
    if let Some(all_of) = obj.get("allOf").and_then(|v| v.as_array()) {
        let child_eval = format!("{}/allOf", eval_path);
        let child_loc = format!("{}/allOf", schema_loc);
        let mut all_children = Vec::new();

        for (idx, sub) in all_of.iter().enumerate() {
            let sub_eval = format!("{}/{}", child_eval, idx);
            let sub_loc = format!("{}/{}", child_loc, idx);
            let sub_child = evaluate_instance(sub, instance, &sub_eval, inst_loc, &sub_loc, ctx, opts);
            all_children.push(sub_child);
        }
        let valid = all_children.iter().all(|c| c.valid);
        let all_node = EvaluationNode {
            evaluation_path: child_eval,
            instance_location: inst_loc.to_string(),
            schema_location: child_loc,
            valid,
            errors: None,
            annotations: None,
            dropped_annotations: None,
            details: Some(all_children),
        };
        children.push(all_node);
    }

    if let Some(any_of) = obj.get("anyOf").and_then(|v| v.as_array()) {
        let child_eval = format!("{}/anyOf", eval_path);
        let child_loc = format!("{}/anyOf", schema_loc);
        let mut any_children = Vec::new();

        for (idx, sub) in any_of.iter().enumerate() {
            let sub_eval = format!("{}/{}", child_eval, idx);
            let sub_loc = format!("{}/{}", child_loc, idx);
            let sub_child = evaluate_instance(sub, instance, &sub_eval, inst_loc, &sub_loc, ctx, opts);
            any_children.push(sub_child);
        }
        let valid = any_children.iter().any(|c| c.valid);
        let mut any_node = EvaluationNode {
            evaluation_path: child_eval,
            instance_location: inst_loc.to_string(),
            schema_location: child_loc,
            valid,
            errors: None,
            annotations: None,
            dropped_annotations: None,
            details: Some(any_children),
        };
        if !valid {
            let mut errs = IndexMap::new();
            errs.insert(
                "anyOf".to_string(),
                format!(
                    "{} is not valid under any of the schemas listed in the 'anyOf' keyword",
                    compact_json(instance)
                ),
            );
            any_node.errors = Some(errs);
        }
        children.push(any_node);
    }

    if let Some(one_of) = obj.get("oneOf").and_then(|v| v.as_array()) {
        let child_eval = format!("{}/oneOf", eval_path);
        let child_loc = format!("{}/oneOf", schema_loc);
        let mut one_children = Vec::new();
        let mut match_count = 0;

        for (idx, sub) in one_of.iter().enumerate() {
            let sub_eval = format!("{}/{}", child_eval, idx);
            let sub_loc = format!("{}/{}", child_loc, idx);
            let sub_child = evaluate_instance(sub, instance, &sub_eval, inst_loc, &sub_loc, ctx, opts);
            if sub_child.valid {
                match_count += 1;
            }
            one_children.push(sub_child);
        }
        let valid = match_count == 1;
        let mut one_node = EvaluationNode {
            evaluation_path: child_eval,
            instance_location: inst_loc.to_string(),
            schema_location: child_loc,
            valid,
            errors: None,
            annotations: None,
            dropped_annotations: None,
            details: Some(one_children),
        };
        if !valid {
            let msg = if match_count == 0 {
                format!(
                    "{} is not valid under any of the schemas listed in the 'oneOf' keyword",
                    compact_json(instance)
                )
            } else {
                format!(
                    "{} is valid under more than one of the schemas listed in the 'oneOf' keyword",
                    compact_json(instance)
                )
            };
            let mut errs = IndexMap::new();
            errs.insert("oneOf".to_string(), msg);
            one_node.errors = Some(errs);
        }
        children.push(one_node);
    }

    if let Some(not_sub) = obj.get("not") {
        let child_eval = format!("{}/not", eval_path);
        let child_loc = format!("{}/not", schema_loc);
        let not_child = evaluate_instance(not_sub, instance, &child_eval, inst_loc, &child_loc, ctx, opts);
        let valid = !not_child.valid;
        let msg = if !valid {
            Some(format!("{} is not allowed for {}", compact_json(not_sub), compact_json(instance)))
        } else {
            None
        };
        children.push(make_kw_node("not", eval_path, inst_loc, schema_loc, valid, msg));
    }

    // if / then / else
    if let Some(if_sub) = obj.get("if") {
        let if_child = evaluate_instance(if_sub, instance, &format!("{}/if", eval_path), inst_loc, &format!("{}/if", schema_loc), ctx, opts);
        if if_child.valid {
            if let Some(then_sub) = obj.get("then") {
                let then_child = evaluate_instance(then_sub, instance, &format!("{}/then", eval_path), inst_loc, &format!("{}/then", schema_loc), ctx, opts);
                children.push(then_child);
            }
        } else if let Some(else_sub) = obj.get("else") {
            let else_child = evaluate_instance(else_sub, instance, &format!("{}/else", eval_path), inst_loc, &format!("{}/else", schema_loc), ctx, opts);
            children.push(else_child);
        }
    }

    node.valid = children.iter().all(|c| c.valid);
    if !children.is_empty() {
        node.details = Some(children);
    }

    node
}

fn flatten_node(node: &EvaluationNode) -> Vec<EvaluationNode> {
    let mut flat = Vec::new();
    let mut item = node.clone();
    item.details = None;
    flat.push(item);
    if let Some(ref details) = node.details {
        for d in details {
            flat.extend(flatten_node(d));
        }
    }
    flat
}

fn collect_leaf_errors(node: &EvaluationNode, errs: &mut Vec<String>) {
    if let Some(ref map) = node.errors {
        for msg in map.values() {
            errs.push(msg.clone());
        }
    }
    if let Some(ref details) = node.details {
        for d in details {
            collect_leaf_errors(d, errs);
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    if args.iter().any(|a| a == "-v" || a == "--version") {
        println!("Version: 0.41.0");
        return;
    }

    let matches = match Command::new("executable")
        .bin_name("executable")
        .arg(
            Arg::new("schema")
                .help("The JSON Schema to validate with (i.e. schema.json)")
                .value_name("SCHEMA")
                .index(1),
        )
        .arg(
            Arg::new("instance")
                .short('i')
                .long("instance")
                .help("A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)")
                .value_name("INSTANCES")
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("draft")
                .short('d')
                .long("draft")
                .help("Enforce a specific JSON Schema draft")
                .value_name("DRAFT")
                .value_parser(["4", "6", "7", "2019", "2020"]),
        )
        .arg(
            Arg::new("assert-format")
                .long("assert-format")
                .help("Turn ON format validation")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("no-assert-format")
                .long("no-assert-format")
                .help("Turn OFF format validation")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("output")
                .long("output")
                .help("Select output style: text (default), flag, list, hierarchical")
                .value_name("OUTPUT")
                .default_value("text")
                .value_parser(["text", "flag", "list", "hierarchical"]),
        )
        .arg(
            Arg::new("version")
                .short('v')
                .long("version")
                .help("Show program's version number and exit")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("errors-only")
                .long("errors-only")
                .help("Only show validation errors")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("connect-timeout")
                .long("connect-timeout")
                .help("Timeout for establishing connections (in seconds)")
                .value_name("SECONDS"),
        )
        .arg(
            Arg::new("timeout")
                .long("timeout")
                .help("Total timeout for HTTP requests (in seconds)")
                .value_name("SECONDS"),
        )
        .arg(
            Arg::new("insecure")
                .short('k')
                .long("insecure")
                .help("Skip TLS certificate verification (dangerous!)")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("cacert")
                .long("cacert")
                .help("Path to a custom CA certificate file (PEM format)")
                .value_name("FILE"),
        )
        .try_get_matches_from(args)
    {
        Ok(m) => m,
        Err(e) => {
            e.exit();
        }
    };

    let schema_path_str = match matches.get_one::<String>("schema") {
        Some(s) => s,
        None => {
            eprintln!("error: the following required arguments were not provided:\n  <SCHEMA>\n\nUsage: executable <SCHEMA>\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    };

    let instance_paths: Vec<String> = matches
        .get_many::<String>("instance")
        .map(|vals| vals.cloned().collect())
        .unwrap_or_default();

    let output_style = matches.get_one::<String>("output").map(|s| s.as_str()).unwrap_or("text");
    let errors_only = matches.get_flag("errors-only");

    let mut assert_format = false;
    for arg in std::env::args() {
        if arg == "--assert-format" {
            assert_format = true;
        } else if arg == "--no-assert-format" {
            assert_format = false;
        }
    }

    let opts = ValidationOptions { assert_format };

    let schema_content = match fs::read_to_string(schema_path_str) {
        Ok(c) => c,
        Err(e) => {
            println!("Error: {}", e);
            std::process::exit(1);
        }
    };

    let schema_json: Value = match serde_json::from_str(&schema_content) {
        Ok(j) => j,
        Err(e) => {
            println!("Error: {}", e);
            std::process::exit(1);
        }
    };

    let schema_path_buf = PathBuf::from(schema_path_str);
    let schema_dir = schema_path_buf.parent().unwrap_or_else(|| Path::new("")).to_path_buf();
    let base_uri = path_to_file_uri(schema_path_str);

    let ctx = SchemaContext {
        base_uri: base_uri.clone(),
        root_schema: schema_json.clone(),
        schema_dir,
    };

    if let Err(e) = validate_schema_meta(&schema_json) {
        if output_style == "text" {
            println!("Schema is invalid. Error: {}", e);
        } else {
            let envelope = OutputEnvelope {
                instance: None,
                output: output_style.to_string(),
                payload: json!({"valid": false}),
                schema: schema_path_str.to_string(),
            };
            println!("{}", serde_json::to_string(&envelope).unwrap());
        }
        std::process::exit(1);
    }

    if instance_paths.is_empty() {
        if output_style == "text" {
            if !errors_only {
                println!("Schema is valid");
            }
        } else {
            let payload = if output_style == "flag" {
                json!({"valid": true})
            } else if output_style == "list" {
                let dummy_node = EvaluationNode {
                    evaluation_path: "".to_string(),
                    instance_location: "".to_string(),
                    schema_location: base_uri,
                    valid: true,
                    errors: None,
                    annotations: None,
                    dropped_annotations: None,
                    details: None,
                };
                json!({"valid": true, "details": vec![dummy_node]})
            } else {
                json!({
                    "valid": true,
                    "evaluationPath": "",
                    "instanceLocation": "",
                    "schemaLocation": base_uri,
                    "details": []
                })
            };
            let envelope = OutputEnvelope {
                instance: None,
                output: output_style.to_string(),
                payload,
                schema: schema_path_str.to_string(),
            };
            if !errors_only {
                println!("{}", serde_json::to_string(&envelope).unwrap());
            }
        }
        std::process::exit(0);
    }

    let mut overall_success = true;

    for inst_path_str in &instance_paths {
        let inst_content = match fs::read_to_string(inst_path_str) {
            Ok(c) => c,
            Err(e) => {
                println!("Error: {}", e);
                std::process::exit(1);
            }
        };

        let inst_json: Value = match serde_json::from_str(&inst_content) {
            Ok(j) => j,
            Err(e) => {
                println!("Error: {}", e);
                std::process::exit(1);
            }
        };

        let eval_tree = evaluate_instance(
            &schema_json,
            &inst_json,
            "",
            "",
            &base_uri,
            &ctx,
            &opts,
        );

        if !eval_tree.valid {
            overall_success = false;
        }

        if errors_only && eval_tree.valid {
            continue;
        }

        if output_style == "text" {
            if eval_tree.valid {
                println!("{} - VALID", inst_path_str);
            } else {
                println!("{} - INVALID. Errors:", inst_path_str);
                let mut leaf_errs = Vec::new();
                collect_leaf_errors(&eval_tree, &mut leaf_errs);
                for (idx, err_msg) in leaf_errs.iter().enumerate() {
                    println!("{}. {}", idx + 1, err_msg);
                }
            }
        } else {
            let payload = match output_style {
                "flag" => json!({"valid": eval_tree.valid}),
                "list" => {
                    let flat = flatten_node(&eval_tree);
                    json!({
                        "valid": eval_tree.valid,
                        "details": flat
                    })
                }
                "hierarchical" => serde_json::to_value(&eval_tree).unwrap(),
                _ => json!({"valid": eval_tree.valid}),
            };

            let envelope = OutputEnvelope {
                instance: Some(inst_path_str.to_string()),
                output: output_style.to_string(),
                payload,
                schema: schema_path_str.to_string(),
            };
            println!("{}", serde_json::to_string(&envelope).unwrap());
        }
    }

    if overall_success {
        std::process::exit(0);
    } else {
        std::process::exit(1);
    }
}
EOF"}

actions.command:
cat <<'EOF' > src/main.rs
use anyhow::{anyhow, Result};
use clap::{Arg, ArgAction, Command};
use indexmap::IndexMap;
use serde::Serialize;
use serde_json::{json, Value};
use std::collections::HashSet;
use std::fs;
use std::path::{Path, PathBuf};
use url::Url;

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct EvaluationNode {
    pub evaluation_path: String,
    pub instance_location: String,
    pub schema_location: String,
    pub valid: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub errors: Option<IndexMap<String, String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub annotations: Option<Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub dropped_annotations: Option<Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub details: Option<Vec<EvaluationNode>>,
}

#[derive(Serialize, Clone, Debug)]
struct OutputEnvelope {
    #[serde(skip_serializing_if = "Option::is_none")]
    instance: Option<String>,
    output: String,
    payload: Value,
    schema: String,
}

struct ValidationOptions {
    assert_format: bool,
}

fn compact_json(v: &Value) -> String {
    serde_json::to_string(v).unwrap_or_else(|_| v.to_string())
}

fn is_type(v: &Value, ty: &str) -> bool {
    match ty {
        "null" => v.is_null(),
        "boolean" => v.is_boolean(),
        "number" => v.is_number(),
        "integer" => {
            if let Some(n) = v.as_number() {
                n.is_i64() || n.is_u64() || (n.is_f64() && n.as_f64().unwrap().fract() == 0.0)
            } else {
                false
            }
        }
        "string" => v.is_string(),
        "array" => v.is_array(),
        "object" => v.is_object(),
        _ => false,
    }
}

fn path_to_file_uri(path_str: &str) -> String {
    let p = Path::new(path_str);
    let abs = if p.is_absolute() {
        p.to_path_buf()
    } else {
        std::env::current_dir().unwrap_or_default().join(p)
    };
    format!("file://{}#", abs.to_string_lossy())
}

struct SchemaContext {
    base_uri: String,
    root_schema: Value,
    schema_dir: PathBuf,
}

impl SchemaContext {
    fn resolve_pointer<'a>(&'a self, root: &'a Value, pointer: &str) -> Option<&'a Value> {
        if pointer.is_empty() || pointer == "#" {
            return Some(root);
        }
        let p = if pointer.starts_with("#/") {
            &pointer[1..]
        } else if pointer.starts_with('/') {
            pointer
        } else {
            return None;
        };
        root.pointer(p)
    }

    fn resolve_ref(&self, ref_str: &str) -> Result<(Value, String)> {
        if ref_str.starts_with('#') {
            if let Some(sub) = self.resolve_pointer(&self.root_schema, ref_str) {
                let loc = format!("{}{}", self.base_uri.trim_end_matches('#'), ref_str);
                Ok((sub.clone(), loc))
            } else {
                Err(anyhow!("Cannot resolve ref {}", ref_str))
            }
        } else if ref_str.starts_with("http://") || ref_str.starts_with("https://") {
            Err(anyhow!(
                "Resource '{}' is not present in a registry and retrieving it failed: error sending request for url ({})",
                ref_str, ref_str
            ))
        } else {
            let (file_part, frag) = if let Some(idx) = ref_str.find('#') {
                (&ref_str[..idx], &ref_str[idx..])
            } else {
                (ref_str, "")
            };
            let target_path = self.schema_dir.join(file_part);
            let content = fs::read_to_string(&target_path)
                .map_err(|_| anyhow!("Resource '{}' is not present in a registry", ref_str))?;
            let sub_json: Value = serde_json::from_str(&content)?;
            let file_uri = path_to_file_uri(&target_path.to_string_lossy());
            let loc = if frag.is_empty() {
                file_uri
            } else {
                format!("{}{}", file_uri.trim_end_matches('#'), frag)
            };
            if frag.is_empty() || frag == "#" {
                Ok((sub_json, loc))
            } else if let Some(sub) = self.resolve_pointer(&sub_json, frag) {
                Ok((sub.clone(), loc))
            } else {
                Err(anyhow!("Cannot resolve ref {}", ref_str))
            }
        }
    }
}

fn validate_schema_meta(schema: &Value) -> Result<()> {
    if schema.is_boolean() {
        return Ok(());
    }
    let obj = match schema.as_object() {
        Some(o) => o,
        None => return Err(anyhow!("Schema must be an object or boolean")),
    };

    if let Some(ty) = obj.get("type") {
        let valid_types = [
            "null", "boolean", "number", "integer", "string", "array", "object",
        ];
        if let Some(s) = ty.as_str() {
            if !valid_types.contains(&s) {
                return Err(anyhow!(
                    "\"{}\" is not valid under any of the schemas listed in the 'anyOf' keyword",
                    s
                ));
            }
        } else if let Some(arr) = ty.as_array() {
            for item in arr {
                if let Some(s) = item.as_str() {
                    if !valid_types.contains(&s) {
                        return Err(anyhow!("\"{}\" is not a valid type", s));
                    }
                } else {
                    return Err(anyhow!("Type array elements must be strings"));
                }
            }
        } else {
            return Err(anyhow!(
                "{} is not valid under any of the schemas listed in the 'anyOf' keyword",
                compact_json(ty)
            ));
        }
    }

    if let Some(min) = obj.get("minimum") {
        if !min.is_number() {
            return Err(anyhow!(
                "{} is not of type \"number\"",
                compact_json(min)
            ));
        }
    }

    if let Some(pat) = obj.get("pattern") {
        if let Some(p) = pat.as_str() {
            if regex::Regex::new(p).is_err() {
                return Err(anyhow!("\"{}\" is not a \"regex\"", p));
            }
        }
    }

    if let Some(props) = obj.get("properties").and_then(|v| v.as_object()) {
        for v in props.values() {
            validate_schema_meta(v)?;
        }
    }
    if let Some(arr) = obj.get("allOf").and_then(|v| v.as_array()) {
        for v in arr {
            validate_schema_meta(v)?;
        }
    }
    if let Some(arr) = obj.get("anyOf").and_then(|v| v.as_array()) {
        for v in arr {
            validate_schema_meta(v)?;
        }
    }
    if let Some(arr) = obj.get("oneOf").and_then(|v| v.as_array()) {
        for v in arr {
            validate_schema_meta(v)?;
        }
    }

    Ok(())
}

fn make_kw_node(
    kw: &str,
    eval_path: &str,
    inst_loc: &str,
    schema_loc: &str,
    valid: bool,
    err_msg: Option<String>,
) -> EvaluationNode {
    let mut err_map = None;
    if let Some(msg) = err_msg {
        let mut map = IndexMap::new();
        map.insert(kw.to_string(), msg);
        err_map = Some(map);
    }
    EvaluationNode {
        evaluation_path: format!("{}/{}", eval_path, kw),
        instance_location: inst_loc.to_string(),
        schema_location: format!("{}/{}", schema_loc, kw),
        valid,
        errors: err_map,
        annotations: None,
        dropped_annotations: None,
        details: None,
    }
}

fn evaluate_instance(
    schema: &Value,
    instance: &Value,
    eval_path: &str,
    inst_loc: &str,
    schema_loc: &str,
    ctx: &SchemaContext,
    opts: &ValidationOptions,
) -> EvaluationNode {
    let mut node = EvaluationNode {
        evaluation_path: eval_path.to_string(),
        instance_location: inst_loc.to_string(),
        schema_location: schema_loc.to_string(),
        valid: true,
        errors: None,
        annotations: None,
        dropped_annotations: None,
        details: None,
    };

    if let Some(b) = schema.as_bool() {
        if !b {
            node.valid = false;
            let mut errs = IndexMap::new();
            errs.insert(
                "false".to_string(),
                format!("False schema does not allow {}", compact_json(instance)),
            );
            node.errors = Some(errs);
        }
        return node;
    }

    let obj = match schema.as_object() {
        Some(o) => o,
        None => return node,
    };

    if let Some(r) = obj.get("$ref").and_then(|v| v.as_str()) {
        match ctx.resolve_ref(r) {
            Ok((ref_schema, ref_loc)) => {
                let next_eval = if eval_path.is_empty() {
                    "/$ref".to_string()
                } else {
                    format!("{}/$ref", eval_path)
                };
                let child = evaluate_instance(
                    &ref_schema,
                    instance,
                    &next_eval,
                    inst_loc,
                    &ref_loc,
                    ctx,
                    opts,
                );
                node.valid = child.valid;
                node.details = Some(vec![child]);
                return node;
            }
            Err(e) => {
                node.valid = false;
                let mut errs = IndexMap::new();
                errs.insert("$ref".to_string(), e.to_string());
                node.errors = Some(errs);
                return node;
            }
        }
    }

    let mut children = Vec::new();

    // 1. type
    if let Some(ty_val) = obj.get("type") {
        if let Some(s) = ty_val.as_str() {
            let valid = is_type(instance, s);
            let msg = if !valid {
                Some(format!("{} is not of type \"{}\"", compact_json(instance), s))
            } else {
                None
            };
            children.push(make_kw_node("type", eval_path, inst_loc, schema_loc, valid, msg));
        } else if let Some(arr) = ty_val.as_array() {
            let types: Vec<&str> = arr.iter().filter_map(|x| x.as_str()).collect();
            let matched = types.iter().any(|t| is_type(instance, t));
            let msg = if !matched {
                let mut sorted_types = types.clone();
                sorted_types.sort();
                let types_str = sorted_types
                    .iter()
                    .map(|t| format!("\"{}\"", t))
                    .collect::<Vec<_>>()
                    .join(", ");
                Some(format!("{} is not of types {}", compact_json(instance), types_str))
            } else {
                None
            };
            children.push(make_kw_node("type", eval_path, inst_loc, schema_loc, matched, msg));
        }
    }

    // 2. enum
    if let Some(enum_val) = obj.get("enum").and_then(|v| v.as_array()) {
        let matched = enum_val.contains(instance);
        let msg = if !matched {
            let options: Vec<String> = enum_val.iter().map(compact_json).collect();
            let options_str = if options.len() > 1 {
                let last = &options[options.len() - 1];
                let rest = &options[..options.len() - 1];
                format!("{} or {}", rest.join(", "), last)
            } else {
                options.join("")
            };
            Some(format!("{} is not one of {}", compact_json(instance), options_str))
        } else {
            None
        };
        children.push(make_kw_node("enum", eval_path, inst_loc, schema_loc, matched, msg));
    }

    // 3. const
    if let Some(const_val) = obj.get("const") {
        let matched = instance == const_val;
        let msg = if !matched {
            Some(format!("{} was expected", compact_json(const_val)))
        } else {
            None
        };
        children.push(make_kw_node("const", eval_path, inst_loc, schema_loc, matched, msg));
    }

    // 4. Number
    if let Some(num) = instance.as_f64() {
        if let Some(min) = obj.get("minimum").and_then(|v| v.as_f64()) {
            let valid = num >= min;
            let msg = if !valid {
                Some(format!("{} is less than the minimum of {}", num, min))
            } else {
                None
            };
            children.push(make_kw_node("minimum", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(max) = obj.get("maximum").and_then(|v| v.as_f64()) {
            let valid = num <= max;
            let msg = if !valid {
                Some(format!("{} is greater than the maximum of {}", num, max))
            } else {
                None
            };
            children.push(make_kw_node("maximum", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(ex_min) = obj.get("exclusiveMinimum").and_then(|v| v.as_f64()) {
            let valid = num > ex_min;
            let msg = if !valid {
                Some(format!("{} is less than or equal to the minimum of {}", num, ex_min))
            } else {
                None
            };
            children.push(make_kw_node("exclusiveMinimum", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(ex_max) = obj.get("exclusiveMaximum").and_then(|v| v.as_f64()) {
            let valid = num < ex_max;
            let msg = if !valid {
                Some(format!("{} is greater than or equal to the maximum of {}", num, ex_max))
            } else {
                None
            };
            children.push(make_kw_node("exclusiveMaximum", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(mult) = obj.get("multipleOf").and_then(|v| v.as_f64()) {
            let valid = (num / mult).fract().abs() < 1e-9;
            let msg = if !valid {
                Some(format!("{} is not a multiple of {}", num, mult))
            } else {
                None
            };
            children.push(make_kw_node("multipleOf", eval_path, inst_loc, schema_loc, valid, msg));
        }
    }

    // 5. String
    if let Some(s) = instance.as_str() {
        let char_count = s.chars().count();
        if let Some(min_len) = obj.get("minLength").and_then(|v| v.as_u64()) {
            let valid = (char_count as u64) >= min_len;
            let msg = if !valid {
                let suffix = if min_len == 1 { "character" } else { "characters" };
                Some(format!("{} is shorter than {} {}", compact_json(instance), min_len, suffix))
            } else {
                None
            };
            children.push(make_kw_node("minLength", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(max_len) = obj.get("maxLength").and_then(|v| v.as_u64()) {
            let valid = (char_count as u64) <= max_len;
            let msg = if !valid {
                let suffix = if max_len == 1 { "character" } else { "characters" };
                Some(format!("{} is longer than {} {}", compact_json(instance), max_len, suffix))
            } else {
                None
            };
            children.push(make_kw_node("maxLength", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(pat_str) = obj.get("pattern").and_then(|v| v.as_str()) {
            if let Ok(re) = regex::Regex::new(pat_str) {
                let valid = re.is_match(s);
                let msg = if !valid {
                    Some(format!("{} does not match \"{}\"", compact_json(instance), pat_str))
                } else {
                    None
                };
                children.push(make_kw_node("pattern", eval_path, inst_loc, schema_loc, valid, msg));
            }
        }
        if opts.assert_format {
            if let Some(fmt) = obj.get("format").and_then(|v| v.as_str()) {
                let valid = match fmt {
                    "email" => s.contains('@') && !s.starts_with('@') && !s.ends_with('@'),
                    "ipv4" => s.parse::<std::net::Ipv4Addr>().is_ok(),
                    "ipv6" => s.parse::<std::net::Ipv6Addr>().is_ok(),
                    "uuid" => s.len() == 36 && s.chars().all(|c| c.is_ascii_hexdigit() || c == '-'),
                    "date-time" => s.contains('T') || s.contains('t'),
                    "uri" => Url::parse(s).is_ok(),
                    _ => true,
                };
                let msg = if !valid {
                    Some(format!("{} is not a \"{}\"", compact_json(instance), fmt))
                } else {
                    None
                };
                children.push(make_kw_node("format", eval_path, inst_loc, schema_loc, valid, msg));
            }
        }
    }

    // 6. Array
    if let Some(arr) = instance.as_array() {
        if let Some(min_items) = obj.get("minItems").and_then(|v| v.as_u64()) {
            let valid = (arr.len() as u64) >= min_items;
            let msg = if !valid {
                let suffix = if min_items == 1 { "item" } else { "items" };
                Some(format!("{} has less than {} {}", compact_json(instance), min_items, suffix))
            } else {
                None
            };
            children.push(make_kw_node("minItems", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(max_items) = obj.get("maxItems").and_then(|v| v.as_u64()) {
            let valid = (arr.len() as u64) <= max_items;
            let msg = if !valid {
                let suffix = if max_items == 1 { "item" } else { "items" };
                Some(format!("{} has more than {} {}", compact_json(instance), max_items, suffix))
            } else {
                None
            };
            children.push(make_kw_node("maxItems", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(uniq) = obj.get("uniqueItems").and_then(|v| v.as_bool()) {
            if uniq {
                let mut set = HashSet::new();
                let mut is_uniq = true;
                for item in arr {
                    let s = compact_json(item);
                    if !set.insert(s) {
                        is_uniq = false;
                        break;
                    }
                }
                let msg = if !is_uniq {
                    Some(format!("{} has non-unique elements", compact_json(instance)))
                } else {
                    None
                };
                children.push(make_kw_node("uniqueItems", eval_path, inst_loc, schema_loc, is_uniq, msg));
            }
        }
        if let Some(contains_schema) = obj.get("contains") {
            let mut any_match = false;
            for item in arr {
                let child = evaluate_instance(
                    contains_schema,
                    item,
                    &format!("{}/contains", eval_path),
                    inst_loc,
                    &format!("{}/contains", schema_loc),
                    ctx,
                    opts,
                );
                if child.valid {
                    any_match = true;
                    break;
                }
            }
            let msg = if !any_match {
                Some(format!("None of {} are valid under the given schema", compact_json(instance)))
            } else {
                None
            };
            children.push(make_kw_node("contains", eval_path, inst_loc, schema_loc, any_match, msg));
        }
    }

    // 7. Object
    if let Some(inst_obj) = instance.as_object() {
        if let Some(min_p) = obj.get("minProperties").and_then(|v| v.as_u64()) {
            let valid = (inst_obj.len() as u64) >= min_p;
            let msg = if !valid {
                let suffix = if min_p == 1 { "property" } else { "properties" };
                Some(format!("{} has less than {} {}", compact_json(instance), min_p, suffix))
            } else {
                None
            };
            children.push(make_kw_node("minProperties", eval_path, inst_loc, schema_loc, valid, msg));
        }
        if let Some(max_p) = obj.get("maxProperties").and_then(|v| v.as_u64()) {
            let valid = (inst_obj.len() as u64) <= max_p;
            let msg = if !valid {
                let suffix = if max_p == 1 { "property" } else { "properties" };
                Some(format!("{} has more than {} {}", compact_json(instance), max_p, suffix))
            } else {
                None
            };
            children.push(make_kw_node("maxProperties", eval_path, inst_loc, schema_loc, valid, msg));
        }

        // required
        if let Some(req_arr) = obj.get("required").and_then(|v| v.as_array()) {
            let mut req_node = make_kw_node("required", eval_path, inst_loc, schema_loc, true, None);
            let mut req_errs = IndexMap::new();
            for req_item in req_arr {
                if let Some(req_str) = req_item.as_str() {
                    if !inst_obj.contains_key(req_str) {
                        req_node.valid = false;
                        req_errs.insert(
                            "required".to_string(),
                            format!("\"{}\" is a required property", req_str),
                        );
                    }
                }
            }
            if !req_node.valid {
                req_node.errors = Some(req_errs);
            }
            children.push(req_node);
        }

        // dependentRequired / dependencies
        let dep_req = obj.get("dependentRequired").or_else(|| obj.get("dependencies"));
        if let Some(dep_map) = dep_req.and_then(|v| v.as_object()) {
            for (prop_key, dep_val) in dep_map {
                if inst_obj.contains_key(prop_key) {
                    if let Some(dep_arr) = dep_val.as_array() {
                        for dep_item in dep_arr {
                            if let Some(dep_str) = dep_item.as_str() {
                                if !inst_obj.contains_key(dep_str) {
                                    let msg = Some(format!("\"{}\" is a required property", dep_str));
                                    children.push(make_kw_node("required", eval_path, inst_loc, schema_loc, false, msg));
                                }
                            }
                        }
                    }
                }
            }
        }

        // properties
        let empty_map = serde_json::Map::new();
        let props = obj.get("properties").and_then(|v| v.as_object()).unwrap_or(&empty_map);
        let has_props_kw = obj.contains_key("properties");

        if has_props_kw {
            let child_eval = format!("{}/properties", eval_path);
            let child_loc = format!("{}/properties", schema_loc);
            let mut prop_children = Vec::new();
            let mut evaluated_keys = Vec::new();

            for (p_name, p_schema) in props {
                if let Some(p_val) = inst_obj.get(p_name) {
                    evaluated_keys.push(p_name.clone());
                    let p_eval = format!("{}/{}", child_eval, p_name);
                    let p_inst_loc = format!("{}/{}", inst_loc, p_name);
                    let p_schema_loc = format!("{}/{}", child_loc, p_name);
                    let p_child = evaluate_instance(
                        p_schema,
                        p_val,
                        &p_eval,
                        &p_inst_loc,
                        &p_schema_loc,
                        ctx,
                        opts,
                    );
                    prop_children.push(p_child);
                }
            }

            let props_valid = prop_children.iter().all(|c| c.valid);
            let child_node = EvaluationNode {
                evaluation_path: child_eval,
                instance_location: inst_loc.to_string(),
                schema_location: child_loc,
                valid: props_valid,
                errors: None,
                annotations: if props_valid {
                    let mut keys: Vec<Value> = evaluated_keys.iter().map(|k| json!(k)).collect();
                    keys.sort_by(|a, b| a.as_str().cmp(&b.as_str()));
                    Some(json!(keys))
                } else {
                    None
                },
                dropped_annotations: if !props_valid {
                    let mut keys: Vec<Value> = evaluated_keys.iter().map(|k| json!(k)).collect();
                    keys.sort_by(|a, b| a.as_str().cmp(&b.as_str()));
                    Some(json!(keys))
                } else {
                    None
                },
                details: if prop_children.is_empty() { None } else { Some(prop_children) },
            };
            children.push(child_node);
        }

        // additionalProperties
        if let Some(add_props) = obj.get("additionalProperties") {
            let known_keys: HashSet<&String> = props.keys().collect();
            let unexpected_keys: Vec<&String> = inst_obj
                .keys()
                .filter(|k| !known_keys.contains(k))
                .collect();

            if let Some(b) = add_props.as_bool() {
                if !b && !unexpected_keys.is_empty() {
                    if has_props_kw {
                        let msg = Some(format!(
                            "Additional properties are not allowed ('{}' was unexpected)",
                            unexpected_keys[0]
                        ));
                        children.push(make_kw_node("additionalProperties", eval_path, inst_loc, schema_loc, false, msg));
                    } else {
                        for k in unexpected_keys {
                            let msg = Some(format!("False schema does not allow {}", compact_json(&inst_obj[k])));
                            children.push(make_kw_node("false", eval_path, inst_loc, schema_loc, false, msg));
                        }
                    }
                }
            } else if add_props.is_object() {
                for k in unexpected_keys {
                    let p_eval = format!("{}/additionalProperties", eval_path);
                    let p_inst_loc = format!("{}/{}", inst_loc, k);
                    let p_schema_loc = format!("{}/additionalProperties", schema_loc);
                    let p_child = evaluate_instance(
                        add_props,
                        &inst_obj[k],
                        &p_eval,
                        &p_inst_loc,
                        &p_schema_loc,
                        ctx,
                        opts,
                    );
                    children.push(p_child);
                }
            }
        }
    }

    // 8. Combinators
    if let Some(all_of) = obj.get("allOf").and_then(|v| v.as_array()) {
        let child_eval = format!("{}/allOf", eval_path);
        let child_loc = format!("{}/allOf", schema_loc);
        let mut all_children = Vec::new();

        for (idx, sub) in all_of.iter().enumerate() {
            let sub_eval = format!("{}/{}", child_eval, idx);
            let sub_loc = format!("{}/{}", child_loc, idx);
            let sub_child = evaluate_instance(sub, instance, &sub_eval, inst_loc, &sub_loc, ctx, opts);
            all_children.push(sub_child);
        }
        let valid = all_children.iter().all(|c| c.valid);
        let all_node = EvaluationNode {
            evaluation_path: child_eval,
            instance_location: inst_loc.to_string(),
            schema_location: child_loc,
            valid,
            errors: None,
            annotations: None,
            dropped_annotations: None,
            details: Some(all_children),
        };
        children.push(all_node);
    }

    if let Some(any_of) = obj.get("anyOf").and_then(|v| v.as_array()) {
        let child_eval = format!("{}/anyOf", eval_path);
        let child_loc = format!("{}/anyOf", schema_loc);
        let mut any_children = Vec::new();

        for (idx, sub) in any_of.iter().enumerate() {
            let sub_eval = format!("{}/{}", child_eval, idx);
            let sub_loc = format!("{}/{}", child_loc, idx);
            let sub_child = evaluate_instance(sub, instance, &sub_eval, inst_loc, &sub_loc, ctx, opts);
            any_children.push(sub_child);
        }
        let valid = any_children.iter().any(|c| c.valid);
        let mut any_node = EvaluationNode {
            evaluation_path: child_eval,
            instance_location: inst_loc.to_string(),
            schema_location: child_loc,
            valid,
            errors: None,
            annotations: None,
            dropped_annotations: None,
            details: Some(any_children),
        };
        if !valid {
            let mut errs = IndexMap::new();
            errs.insert(
                "anyOf".to_string(),
                format!(
                    "{} is not valid under any of the schemas listed in the 'anyOf' keyword",
                    compact_json(instance)
                ),
            );
            any_node.errors = Some(errs);
        }
        children.push(any_node);
    }

    if let Some(one_of) = obj.get("oneOf").and_then(|v| v.as_array()) {
        let child_eval = format!("{}/oneOf", eval_path);
        let child_loc = format!("{}/oneOf", schema_loc);
        let mut one_children = Vec::new();
        let mut match_count = 0;

        for (idx, sub) in one_of.iter().enumerate() {
            let sub_eval = format!("{}/{}", child_eval, idx);
            let sub_loc = format!("{}/{}", child_loc, idx);
            let sub_child = evaluate_instance(sub, instance, &sub_eval, inst_loc, &sub_loc, ctx, opts);
            if sub_child.valid {
                match_count += 1;
            }
            one_children.push(sub_child);
        }
        let valid = match_count == 1;
        let mut one_node = EvaluationNode {
            evaluation_path: child_eval,
            instance_location: inst_loc.to_string(),
            schema_location: child_loc,
            valid,
            errors: None,
            annotations: None,
            dropped_annotations: None,
            details: Some(one_children),
        };
        if !valid {
            let msg = if match_count == 0 {
                format!(
                    "{} is not valid under any of the schemas listed in the 'oneOf' keyword",
                    compact_json(instance)
                )
            } else {
                format!(
                    "{} is valid under more than one of the schemas listed in the 'oneOf' keyword",
                    compact_json(instance)
                )
            };
            let mut errs = IndexMap::new();
            errs.insert("oneOf".to_string(), msg);
            one_node.errors = Some(errs);
        }
        children.push(one_node);
    }

    if let Some(not_sub) = obj.get("not") {
        let child_eval = format!("{}/not", eval_path);
        let child_loc = format!("{}/not", schema_loc);
        let not_child = evaluate_instance(not_sub, instance, &child_eval, inst_loc, &child_loc, ctx, opts);
        let valid = !not_child.valid;
        let msg = if !valid {
            Some(format!("{} is not allowed for {}", compact_json(not_sub), compact_json(instance)))
        } else {
            None
        };
        children.push(make_kw_node("not", eval_path, inst_loc, schema_loc, valid, msg));
    }

    // if / then / else
    if let Some(if_sub) = obj.get("if") {
        let if_child = evaluate_instance(if_sub, instance, &format!("{}/if", eval_path), inst_loc, &format!("{}/if", schema_loc), ctx, opts);
        if if_child.valid {
            if let Some(then_sub) = obj.get("then") {
                let then_child = evaluate_instance(then_sub, instance, &format!("{}/then", eval_path), inst_loc, &format!("{}/then", schema_loc), ctx, opts);
                children.push(then_child);
            }
        } else if let Some(else_sub) = obj.get("else") {
            let else_child = evaluate_instance(else_sub, instance, &format!("{}/else", eval_path), inst_loc, &format!("{}/else", schema_loc), ctx, opts);
            children.push(else_child);
        }
    }

    node.valid = children.iter().all(|c| c.valid);
    if !children.is_empty() {
        node.details = Some(children);
    }

    node
}

fn flatten_node(node: &EvaluationNode) -> Vec<EvaluationNode> {
    let mut flat = Vec::new();
    let mut item = node.clone();
    item.details = None;
    flat.push(item);
    if let Some(ref details) = node.details {
        for d in details {
            flat.extend(flatten_node(d));
        }
    }
    flat
}

fn collect_leaf_errors(node: &EvaluationNode, errs: &mut Vec<String>) {
    if let Some(ref map) = node.errors {
        for msg in map.values() {
            errs.push(msg.clone());
        }
    }
    if let Some(ref details) = node.details {
        for d in details {
            collect_leaf_errors(d, errs);
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    if args.iter().any(|a| a == "-v" || a == "--version") {
        println!("Version: 0.41.0");
        return;
    }

    let matches = match Command::new("executable")
        .bin_name("executable")
        .arg(
