                instance: None,
                output: output_style.to_string(),
                payload: json!({"valid": false}),
                schema: schema_path_str.to_string(),
            };
            println!("{}", serde_json::to_string(&envelope).unwrap());
        }
        std::process::exit(1);
    }

    if instance_paths.is_empty() {
        if output_style == "text" {
            if !errors_only {
                println!("Schema is valid");
            }
        } else {
            let payload = if output_style == "flag" {
                json!({"valid": true})
            } else if output_style == "list" {
                let dummy_node = EvaluationNode {
                    evaluation_path: "".to_string(),
                    instance_location: "".to_string(),
                    schema_location: base_uri,
                    valid: true,
                    errors: None,
                    annotations: None,
                    dropped_annotations: None,
                    details: None,
                };
                json!({"valid": true, "details": vec![dummy_node]})
            } else {
                json!({
                    "valid": true,
                    "evaluationPath": "",
                    "instanceLocation": "",
                    "schemaLocation": base_uri,
                    "details": []
                })
            };
            let envelope = OutputEnvelope {
                instance: None,
                output: output_style.to_string(),
                payload,
                schema: schema_path_str.to_string(),
            };
            if !errors_only {
                println!("{}", serde_json::to_string(&envelope).unwrap());
            }
        }
        std::process::exit(0);
    }

    let mut overall_success = true;

    for inst_path_str in &instance_paths {
        let inst_content = match fs::read_to_string(inst_path_str) {
            Ok(c) => c,
            Err(e) => {
                println!("Error: {}", e);
                std::process::exit(1);
            }
        };

        let inst_json: Value = match serde_json::from_str(&inst_content) {
            Ok(j) => j,
            Err(e) => {
                println!("Error: {}", e);
                std::process::exit(1);
            }
        };

        let eval_tree = evaluate_instance(
            &schema_json,
            &inst_json,
            "",
            "",
            &base_uri,
            &ctx,
            &opts,
        );

        if !eval_tree.valid {
            overall_success = false;
        }

        if errors_only && eval_tree.valid {
            continue;
        }

        if output_style == "text" {
            if eval_tree.valid {
                println!("{} - VALID", inst_path_str);
            } else {
                println!("{} - INVALID. Errors:", inst_path_str);
                let mut leaf_errs = Vec::new();
                collect_leaf_errors(&eval_tree, &mut leaf_errs);
                for (idx, err_msg) in leaf_errs.iter().enumerate() {
                    println!("{}. {}", idx + 1, err_msg);
                }
            }
        } else {
            let payload = match output_style {
                "flag" => json!({"valid": eval_tree.valid}),
                "list" => {
                    let flat = flatten_node(&eval_tree);
                    json!({
                        "valid": eval_tree.valid,
                        "details": flat
                    })
                }
                "hierarchical" => serde_json::to_value(&eval_tree).unwrap(),
                _ => json!({"valid": eval_tree.valid}),
            };

            let envelope = OutputEnvelope {
                instance: Some(inst_path_str.to_string()),
                output: output_style.to_string(),
                payload,
                schema: schema_path_str.to_string(),
            };
            println!("{}", serde_json::to_string(&envelope).unwrap());
        }
    }

    if overall_success {
        std::process::exit(0);
    } else {
        std::process::exit(1);
    }
}
